#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 100005
#define INF 1000000000000000000LL

typedef long long ll;

typedef struct Edge {
    int to, next;
    ll cost;
} Edge;

Edge edges[MAXN * 2];
int head[MAXN], edge_cnt;
int is_base[MAXN];
int n, k, t;
ll dp[MAXN][2]; // dp[node][0] = min cost to cut this subtree with node connected to parent
                // dp[node][1] = min cost to cut so that base group ending at node has size <= k

void add_edge(int u, int v, ll c) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].cost = c;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

void dfs(int u, int parent) {
    // dp[u][0] : node is part of a group that still connects upward
    // dp[u][1] : node's group is already separated from parent (cut above)
    dp[u][0] = 0;
    dp[u][1] = INF;

    ll sum0 = 0;
    // First compute sum of dp[v][0] (no cut below)
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v == parent) continue;
        dfs(v, u);
        sum0 += dp[v][0];
    }

    if (is_base[u]) {
        // base must be in its own region eventually
        // if we cut below, we can separate.
        dp[u][0] = sum0; // keep all children connected upward (they will be cut above if needed)
        dp[u][1] = INF;  // can't have base already separated from parent without cutting something
    } else {
        // non-base: either keep all children or cut all connections to separate
        dp[u][0] = sum0;
        // try to cut this node from parent by cutting all edges to children
        dp[u][1] = sum0;
    }

    // Now try cutting one child to limit group size
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v == parent) continue;
        ll cut_cost = edges[i].cost;
        // if we cut edge u-v, v's group becomes separate
        ll new_val = sum0 - dp[v][0] + dp[v][1] + cut_cost;
        if (new_val < dp[u][0]) dp[u][0] = new_val;
        if (new_val < dp[u][1]) dp[u][1] = new_val;
    }
}

int main() {
    memset(head, -1, sizeof(head));
    scanf("%d %d %d", &n, &t, &k);
    for (int i = 0; i < t; i++) {
        int x;
        scanf("%d", &x);
        is_base[x] = 1;
    }
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        ll c;
        scanf("%d %d %lld", &u, &v, &c);
        add_edge(u, v, c);
        add_edge(v, u, c);
    }

    dfs(1, 0);

    // We need exactly k cuts, but dp tracks one cut per separated group.
    // Since tree starts as one region, we need k cuts to get k+1 regions.
    // Our dp minimizes cost for separating into groups each containing at least one base.
    // We output dp[1][0] because root has no parent, so group containing root is final.

    printf("%lld\n", dp[1][0]);
    return 0;
}

