#define MAXN 100005

int head[MAXN], nxt[2*MAXN], to[2*MAXN], ecnt;
int cost[2*MAXN];
int base_count[MAXN];
int is_base[MAXN];
int n, t, k;
int valid_costs[MAXN];
int vcnt;

void add_edge(int u, int v, int c) {
    ecnt++;
    to[ecnt] = v; cost[ecnt] = c; nxt[ecnt] = head[u]; head[u] = ecnt;
    ecnt++;
    to[ecnt] = u; cost[ecnt] = c; nxt[ecnt] = head[v]; head[v] = ecnt;
}

void dfs(int u, int par) {
    base_count[u] = is_base[u];
    for (int e = head[u]; e; e = nxt[e]) {
        int v = to[e];
        if (v == par) continue;
        dfs(v, u);
        base_count[u] += base_count[v];
        // edge between u and v has cost[e]
        // subtree of v has base_count[v] bases
        if (base_count[v] >= 1 && base_count[v] <= t-1) {
            valid_costs[vcnt++] = cost[e];
        }
    }
}

int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

