#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct Edge {
    int to, next;
    ll w;
} Edge;

static const ll INF = (ll)4e18;

int n, k, tcnt;
int *isBase;

Edge *edges;
int *head;
int ecnt = 0;

int *parentArr, *order, *subBase;
ll *parW;

ll **dp;

void addEdge(int u, int v, ll w) {
    edges[ecnt].to = v;
    edges[ecnt].w = w;
    edges[ecnt].next = head[u];
    head[u] = ecnt++;
}

ll minll(ll a, ll b) { return a < b ? a : b; }

int main() {
    if (scanf("%d %d %d", &n, &tcnt, &k) != 3) return 0;

    isBase = (int*)calloc(n + 1, sizeof(int));
    head = (int*)malloc((n + 1) * sizeof(int));
    parentArr = (int*)malloc((n + 1) * sizeof(int));
    order = (int*)malloc((n + 1) * sizeof(int));
    subBase = (int*)malloc((n + 1) * sizeof(int));
    parW = (ll*)malloc((n + 1) * sizeof(ll));

    for (int i = 1; i <= n; i++) head[i] = -1;

    edges = (Edge*)malloc((2 * (n - 1)) * sizeof(Edge));

    for (int i = 0; i < tcnt; i++) {
        int x;
        scanf("%d", &x);
        isBase[x] = 1;
    }

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        ll w;
        scanf("%d %d %lld", &u, &v, &w);
        addEdge(u, v, w);
        addEdge(v, u, w);
    }

    if (k == 0) {
        printf("0\n");
        return 0;
    }

    if (k > tcnt - 1) {
        printf("-1\n");
        return 0;
    }

    /* Root the tree at 1 and get traversal order */
    int *stack = (int*)malloc(n * sizeof(int));
    int top = 0, ordsz = 0;
    stack[top++] = 1;
    parentArr[1] = 0;
    parW[1] = 0;

    while (top) {
        int u = stack[--top];
        order[ordsz++] = u;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (v == parentArr[u]) continue;
            parentArr[v] = u;
            parW[v] = edges[e].w;
            stack[top++] = v;
        }
    }
    free(stack);

    /* subtree base counts */
    for (int i = ordsz - 1; i >= 0; i--) {
        int u = order[i];
        subBase[u] = isBase[u];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (parentArr[v] == u) subBase[u] += subBase[v];
        }
    }

    /* dp[u][j] = min cost to make j cuts inside subtree of u,
       while keeping the component containing u connected upward.
       Every detached component created inside subtree(u) must contain at least one base.
    */
    dp = (ll**)malloc((n + 1) * sizeof(ll*));
    for (int i = 1; i <= n; i++) {
        dp[i] = (ll*)malloc((k + 1) * sizeof(ll));
        for (int j = 0; j <= k; j++) dp[i][j] = INF;
    }

    int *sz = (int*)calloc(n + 1, sizeof(int));
    ll *tmp = (ll*)malloc((k + 1) * sizeof(ll));

    for (int idx = ordsz - 1; idx >= 0; idx--) {
        int u = order[idx];
        dp[u][0] = 0;
        sz[u] = 0;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (parentArr[v] != u) continue;

            for (int j = 0; j <= k; j++) tmp[j] = INF;

            for (int a = 0; a <= sz[u] && a <= k; a++) {
                if (dp[u][a] >= INF) continue;

                /* Option 1: keep edge (u,v), merge child's open component */
                for (int b = 0; b <= sz[v] && a + b <= k; b++) {
                    if (dp[v][b] >= INF) continue;
                    tmp[a + b] = minll(tmp[a + b], dp[u][a] + dp[v][b]);
                }

                /* Option 2: cut edge (u,v)
                   valid only if subtree(v) has at least one base,
                   so the detached region contains a base.
                */
                if (subBase[v] > 0 && a + 1 <= k) {
                    for (int b = 0; b <= sz[v] && a + b + 1 <= k; b++) {
                        if (dp[v][b] >= INF) continue;
                        tmp[a + b + 1] = minll(tmp[a + b + 1], dp[u][a] + dp[v][b] + edges[e].w);
                    }
                }
            }

            sz[u] += sz[v] + 1;
            if (sz[u] > k) sz[u] = k;
            for (int j = 0; j <= sz[u]; j++) dp[u][j] = tmp[j];
            for (int j = sz[u] + 1; j <= k; j++) dp[u][j] = INF;
        }
    }

    /* Final answer:
       After k cuts, all k detached components are guaranteed to have bases.
       The remaining root component must also contain at least one base.
       Since total bases >= k+1 and all detached parts have bases, root part automatically has one.
       So answer is dp[1][k].
    */
    if (dp[1][k] >= INF / 2) printf("-1\n");
    else printf("%lld\n", dp[1][k]);

    for (int i = 1; i <= n; i++) free(dp[i]);
    free(dp);
    free(sz);
    free(tmp);
    free(isBase);
    free(head);
    free(parentArr);
    free(order);
    free(subBase);
    free(parW);
    free(edges);

    return 0;
}

