const int64 INF = 1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t, k;
    cin >> n >> t >> k;
    vector<int> base(n, 0);
    for (int i = 0; i < t; i++) {
        int x;
        cin >> x;
        base[x] = 1;
    }

    vector<vector<pair<int,int>>> adj(n);
    for (int i = 0; i < n-1; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    // dp[u][j][f]  f=0: no base in u's current component yet, f=1: has base
    vector dp(n, vector(k+2, vector<int64>(2, INF)));
    vector<int> sz(n, 0);

    function<void(int,int)> dfs = [&](int u, int parent) {
        sz[u] = 1;
        dp[u][0][base[u]] = 0;

        for (auto &[v, cost] : adj[u]) {
            if (v == parent) continue;
            dfs(v, u);

            vector tmp(k+2, vector<int64>(2, INF));

            for (int i = 0; i <= min(sz[u], k); i++) {
                for (int fu = 0; fu < 2; fu++) {
                    if (dp[u][i][fu] == INF) continue;
                    for (int j = 0; j <= min(sz[v], k-i); j++) {
                        for (int fv = 0; fv < 2; fv++) {
                            if (dp[v][j][fv] == INF) continue;
                            // cut edge
                            if (fv == 1 && i+j+1 <= k) {
                                tmp[i+j+1][fu] = min(tmp[i+j+1][fu], dp[u][i][fu] + dp[v][j][fv] + cost);
                            }
                            // keep edge
                            if (i+j <= k) {
                                int nfu = fu | fv;
                                tmp[i+j][nfu] = min(tmp[i+j][nfu], dp[u][i][fu] + dp[v][j][fv]);
                            }
                        }
                    }
                }
            }

            dp[u] = tmp;
            sz[u] += sz[v];
        }
    };

    dfs(0, -1);

    int64 ans = INF;
    for (int i = 0; i <= k; i++) {
        ans = min(ans, dp[0][i][1]);
    }
    cout << ans << "\n";

    return 0;
}

