const long long INF = 1e18;
int n, t, k;
vector<pair<int,int>> adj[100005];
bool isBase[100005];
vector<long long> dp[100005];
int sz[100005]; // number of bases in subtree

void dfs(int u, int par) {
    sz[u] = isBase[u] ? 1 : 0;
    dp[u].assign(1, 0); // dp[u][0] = 0 if base, else INF
    if (!isBase[u]) dp[u][0] = INF;

    for (auto [v, w] : adj[u]) {
        if (v == par) continue;
        dfs(v, u);

        int newSize = sz[u] + sz[v];
        vector<long long> ndp(min(newSize, k+1) + 1, INF); // at most min(newSize-1, k) cuts
        // actually cuts can be at most newSize-1
        int maxCuts = min((int)dp[u].size()-1 + (int)dp[v].size()-1 + 1, k);
        ndp.assign(maxCuts+1, INF);

        for (int a = 0; a < (int)dp[u].size(); a++) {
            if (dp[u][a] == INF) continue;
            for (int b = 0; b < (int)dp[v].size(); b++) {
                if (dp[v][b] == INF) continue;
                // don't cut
                if (a+b <= maxCuts) ndp[a+b] = min(ndp[a+b], dp[u][a]+dp[v][b]);
                // cut edge
                if (a+b+1 <= maxCuts) ndp[a+b+1] = min(ndp[a+b+1], dp[u][a]+dp[v][b]+w);
            }
        }
        sz[u] = newSize;
        dp[u] = ndp;
    }
}

