#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);

struct Edge {
    int to;
    ll w;
};

int n, k, t;
vector<vector<Edge>> g;
vector<int> hasBase;
vector<int> parentNode;
vector<ll> parentCost;
vector<int> order;

vector<vector<ll>> dp;
vector<int> basesInSubtree;

void dfs(int root = 1) {
    parentNode.assign(n + 1, 0);
    parentCost.assign(n + 1, 0);
    order.clear();
    order.reserve(n);

    stack<int> st;
    st.push(root);
    parentNode[root] = -1;

    while (!st.empty()) {
        int u = st.top();
        st.pop();
        order.push_back(u);
        for (auto &e : g[u]) {
            int v = e.to;
            if (v == parentNode[u]) continue;
            parentNode[v] = u;
            parentCost[v] = e.w;
            st.push(v);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k >> t;
    g.assign(n + 1, {});
    hasBase.assign(n + 1, 0);

    for (int i = 0; i < t; ++i) {
        int x;
        cin >> x;
        hasBase[x] = 1;
    }

    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        ll c;
        cin >> u >> v >> c;
        g[u].push_back({v, c});
        g[v].push_back({u, c});
    }

    // Need exactly k cuts => k+1 regions, each with at least one base.
    // Equivalent: partition tree into k+1 connected components, each containing >=1 base.
    // Root tree at 1. DP on subtree:
    // dp[u][j] = minimum cost inside subtree of u so that after cuts within subtree,
    //            there are exactly j components containing bases in subtree of u,
    //            and the component containing u is kept connected to u's parent.
    //
    // For a child v:
    // - keep edge (u,v): then one of v's components (the one containing v) merges into u's component,
    //   so if subtree v contributes x components, total added is x-1, cost dp[v][x]
    // - cut edge (u,v): then subtree v must be fully valid on its own, contributes x components,
    //   cost dp[v][x] + edge_cost
    //
    // Initialization at u: only u itself contributes one open component if hasBase[u], else zero.
    //
    // At root, there is no parent, so the open component is also a final component.
    // Therefore answer is dp[root][k+1].

    dfs(1);

    dp.assign(n + 1, vector<ll>(k + 2, INF));
    basesInSubtree.assign(n + 1, 0);

    for (int idx = n - 1; idx >= 0; --idx) {
        int u = order[idx];

        vector<ll> cur(k + 2, INF);
        cur[hasBase[u]] = 0;
        int curMax = hasBase[u];
        basesInSubtree[u] = hasBase[u];

        for (auto &e : g[u]) {
            int v = e.to;
            if (v == parentNode[u]) continue;

            vector<ll> nxt(k + 2, INF);
            int childMax = min(basesInSubtree[v], k + 1);

            for (int a = 0; a <= curMax; ++a) {
                if (cur[a] >= INF) continue;
                for (int b = 1; b <= childMax; ++b) {
                    if (dp[v][b] >= INF) continue;

                    // Keep edge u-v: child's open component merges with u's open component
                    if (a + b - 1 <= k + 1) {
                        nxt[a + b - 1] = min(nxt[a + b - 1], cur[a] + dp[v][b]);
                    }

                    // Cut edge u-v: all child's b components stay separate
                    if (a + b <= k + 1) {
                        nxt[a + b] = min(nxt[a + b], cur[a] + dp[v][b] + e.w);
                    }
                }
            }

            cur = move(nxt);
            curMax = min(k + 1, curMax + childMax);
            basesInSubtree[u] += basesInSubtree[v];
        }

        int limit = min(k + 1, basesInSubtree[u]);
        for (int j = 0; j <= limit; ++j) dp[u][j] = cur[j];
    }

    ll ans = dp[1][k + 1];
    cout << ans << '\n';
    return 0;
}

import java.util.*;
import java.io.*;

public class Main {
    static List<int[]>[] adj;
    static boolean[] hasBase;
    static long INF = Long.MAX_VALUE / 2;
    static long[][] dp;
    static int[] size;
    static int target;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        target = k + 1; // we need exactly k+1 components

        hasBase = new boolean[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < t; i++) {
            int node = Integer.parseInt(st.nextToken()) - 1;
            hasBase[node] = true;
        }

        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();

        for (int i = 0; i < n - 1; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            int c = Integer.parseInt(st.nextToken());
            adj[u].add(new int[]{v, c});
            adj[v].add(new int[]{u, c});
        }

        dp = new long[n][target + 1];
        size = new int[n];
        dfs(0, -1);

        System.out.println(dp[0][target]);
    }

    static void dfs(int u, int parent) {
        // Initialize dp for u
        for (int j = 0; j <= target; j++) dp[u][j] = INF;
        dp[u][1] = 0; // one component: just itself
        size[u] = hasBase[u] ? 1 : 0;

        for (int[] edge : adj[u]) {
            int v = edge[0];
            int cost = edge[1];
            if (v == parent) continue;
            dfs(v, u);

            long[] newDp = new long[target + 1];
            Arrays.fill(newDp, INF);

            // combine current u's components with child's components
            for (int i = 1; i <= Math.min(size[u], target); i++) {
                if (dp[u][i] >= INF) continue;
                for (int j = 0; j <= Math.min(size[v], target - i); j++) {
                    if (dp[v][j] >= INF) continue;
                    // option 1: keep edge (don't cut)
                    long val = dp[u][i] + dp[v][j];
                    if (i + j <= target) {
                        newDp[i + j] = Math.min(newDp[i + j], val);
                    }
                }
                // option 2: cut edge (only if child's subtree has at least one base)
                if (size[v] > 0) {
                    for (int j = 1; j <= Math.min(size[v], target - i + 1); j++) {
                        if (dp[v][j] >= INF) continue;
                        long val = dp[u][i] + dp[v][j] + cost;
                        if (i + j - 1 <= target) {
                            newDp[i + j - 1] = Math.min(newDp[i + j - 1], val);
                        }
                    }
                }
            }

            // also consider cutting edge when u had only itself and child had only one component
            // (already handled in loops above)

            size[u] += size[v];
            dp[u] = newDp;
        }
    }
}

