            adj[u].add(new int[]{v,w});
            adj[v].add(new int[]{u,w});
        }
        dp = new long[n+1][];
        dfs(1,0);
        System.out.println(dp[1][k]);
    }

    static void dfs(int u, int par){
        sz[u]=1;
        dp[u] = new long[]{isBase[u]?0:INF};
        for(int[] e: adj[u]){
            int v=e[0]; long w=e[1];
            if(v==par) continue;
            dfs(v,u);
            int newSz = sz[u]+sz[v];
            long[] ndp = new long[newSz];
            Arrays.fill(ndp,INF);
            for(int i=0;i<sz[u];i++){
                if(dp[u][i]==INF) continue;
                for(int j=0;j<sz[v];j++){
                    if(dp[v][j]==INF) continue;
                    if(i+j<newSz) ndp[i+j]=Math.min(ndp[i+j],dp[u][i]+dp[v][j]);
                    if(i+j+1<newSz) ndp[i+j+1]=Math.min(ndp[i+j+1],dp[u][i]+dp[v][j]+w);
                }
            }
            sz[u]=newSz;
            dp[u]=ndp;
        }
    }
}

import java.io.*;
import java.util.*;

/*
We need remove exactly k edges from a tree so that after removal, each of the k+1 components
contains at least one military base, and total removed-edge cost is minimized.

Equivalent:
Choose k edges to cut. In a tree, every resulting component must contain a base.
That means no component can be base-free.

Root the tree arbitrarily, say at 1.
For any cut edge between parent p and child u, the detached subtree of u must contain at least one base,
and the remaining part must also contain at least one base. If total number of bases is t and 1 <= basesInSubtree(u) <= t-1,
then cutting this edge is individually valid.

Now if we cut several edges, validity of all components is equivalent to:
every component has at least one base.

Tree DP:
dp[u][j] = minimum cost to cut j edges inside the rooted subtree of u, such that
every connected component fully contained in subtree(u) after these cuts has at least one base,
EXCEPT the component containing u is allowed to be "open" upward and may or may not rely on ancestors for bases.

To make this precise, we need whether the open component containing u currently has a base inside subtree(u).
State:
dp[u][j][b], b in {0,1}
- considering only nodes in subtree(u)
- after cutting j edges inside subtree(u)
- every closed component entirely inside subtree(u) has at least one base
- the component containing u has base-presence flag b within subtree(u)

At the end for root r, the open component is the whole remaining root component, so it also must contain a base.
Thus answer = dp[root][k][1].

Transitions when processing child v of u:
We can either keep edge (u,v), merging u-open component with v-open component;
or cut edge (u,v), which is allowed only if v-open component has a base (b=1), because then it becomes a closed component.

Complexities: O(n * k^2).

Input format is not explicitly given, so we assume common format:
n t k
t base node indices
then n-1 lines: u v w

This is the most standard interpretation.
*/

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static int n, t, k;
    static ArrayList<Edge>[] g;
    static boolean[] isBase;
    static int[] parent;
    static long[] parentW;
    static int[] order;
    static int[] subSize;
    static final long INF = (long) 4e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        n = fs.nextInt();
        t = fs.nextInt();
        k = fs.nextInt();

        g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();
        isBase = new boolean[n + 1];

        for (int i = 0; i < t; i++) {
            int x = fs.nextInt();
            isBase[x] = true;
        }

        for (int i = 0; i < n - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            long w = fs.nextLong();
            g[u].add(new Edge(v, w));
            g[v].add(new Edge(u, w));
        }

        if (k >= t) {
            System.out.println(-1);
            return;
        }

        buildRootedTree(1);

        // DP arrays per node:
        // dp0[u][j] = cost with open component at u having no base in subtree(u)
        // dp1[u][j] = cost with open component at u having at least one base in subtree(u)
        long[][] dp0 = new long[n + 1][k + 1];
        long[][] dp1 = new long[n + 1][k + 1];
        for (int i = 1; i <= n; i++) {
            Arrays.fill(dp0[i], INF);
            Arrays.fill(dp1[i], INF);
        }

        // postorder
        for (int idx = n - 1; idx >= 0; idx--) {
            int u = order[idx];

            long[] cur0 = new long[k + 1];
            long[] cur1 = new long[k + 1];
            Arrays.fill(cur0, INF);
            Arrays.fill(cur1, INF);

            if (isBase[u]) cur1[0] = 0;
            else cur0[0] = 0;

            int used = 0;

            for (Edge e : g[u]) {
                int v = e.to;
                if (parent[v] != u) continue;

                long[] nxt0 = new long[k + 1];
                long[] nxt1 = new long[k + 1];
                Arrays.fill(nxt0, INF);
                Arrays.fill(nxt1, INF);

                for (int a = 0; a <= used && a <= k; a++) {
                    if (cur0[a] >= INF && cur1[a] >= INF) continue;
                    for (int b = 0; b + a <= k; b++) {
                        // keep edge u-v: merge open components
                        if (dp0[v][b] < INF) {
                            if (cur0[a] < INF) {
                                nxt0[a + b] = Math.min(nxt0[a + b], cur0[a] + dp0[v][b]);
                            }
                            if (cur1[a] < INF) {
                                nxt1[a + b] = Math.min(nxt1[a + b], cur1[a] + dp0[v][b]);
                            }
                        }
                        if (dp1[v][b] < INF) {
                            if (cur0[a] < INF) {
                                nxt1[a + b] = Math.min(nxt1[a + b], cur0[a] + dp1[v][b]);
                            }
                            if (cur1[a] < INF) {
                                nxt1[a + b] = Math.min(nxt1[a + b], cur1[a] + dp1[v][b]);
                            }
                        }

                        // cut edge u-v: v-side becomes closed, so it must have a base => child state must be 1
                        if (a + b + 1 <= k && dp1[v][b] < INF) {
                            long add = dp1[v][b] + e.w;
                            if (cur0[a] < INF) {
                                nxt0[a + b + 1] = Math.min(nxt0[a + b + 1], cur0[a] + add);
                            }
                            if (cur1[a] < INF) {
                                nxt1[a + b + 1] = Math.min(nxt1[a + b + 1], cur1[a] + add);
                            }
                        }
                    }
                }

                used = Math.min(k, used + subSize[v]);
                cur0 = nxt0;
                cur1 = nxt1;
            }

            dp0[u] = cur0;
            dp1[u] = cur1;
        }

        long ans = dp1[1][k];
        System.out.println(ans >= INF ? -1 : ans);
    }

    static void buildRootedTree(int root) {
        parent = new int[n + 1];
        parentW = new long[n + 1];
        order = new int[n];
        subSize = new int[n + 1];

        int[] stack = new int[n];
        int top = 0;
        stack[top++] = root;
        parent[root] = -1;

        int idx = 0;
        while (top > 0) {
            int u = stack[--top];
            order[idx++] = u;
            for (Edge e : g[u]) {
                int v = e.to;
                if (v == parent[u]) continue;
                parent[v] = u;
                parentW[v] = e.w;
                stack[top++] = v;
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            subSize[u] = 1;
            for (Edge e : g[u]) {
                int v = e.to;
                if (parent[v] == u) subSize[u] += subSize[v];
            }
        }
    }
}

import sys
sys.setrecursionlimit(300000)

def solve():
    input_data = sys.stdin.read().strip().split()
    n, t, k = map(int, input_data[:3])
    bases = list(map(int, input_data[3:3+t]))
    edges = []
    idx = 3 + t
    adj = [[] for _ in range(n)]
    for _ in range(n-1):
        u, v, w = map(int, input_data[idx:idx+3])
        idx += 3
        u -= 1
        v -= 1
        adj[u].append((v, w))
        adj[v].append((u, w))

    has_base = [False]*n
    for b in bases:
        has_base[b-1] = True

    INF = 10**18

    def dfs(u, parent):
        # dp[c][b] = min cost, c = components in subtree (with base), b = does u's component have base
        dp = [[INF, INF] for _ in range(2)]
        dp[1][1 if has_base[u] else 0] = 0  # initially one component (just node u)

        for v, w in adj[u]:
            if v == parent:
                continue
            child_dp = dfs(v, u)
            new_dp = [[INF, INF] for _ in range(len(dp) + len(child_dp) - 1)]
            for c1 in range(1, len(dp)):
                for b1 in range(2):
                    if dp[c1][b1] == INF:
                        continue
                    for c2 in range(1, len(child_dp)):
                        for b2 in range(2):
                            if child_dp[c2][b2] == INF:
                                continue
                            # keep edge
                            if b1 or b2:
                                nb = 1
                            else:
                                nb = 0
                            nc = c1 + c2 - 1
                            val = dp[c1][b1] + child_dp[c2][b2]
                            if val < new_dp[nc][nb]:
                                new_dp[nc][nb] = val
                            # cut edge — child's component must have a base
                            if b2 == 1:
                                nc = c1 + c2
                                val = dp[c1][b1] + child_dp[c2][b2] + w
                                if val < new_dp[nc][b1]:
                                    new_dp[nc][b1] = val
            dp = new_dp
        return dp

    dp_root = dfs(0, -1)
    ans = INF
    # need k+1 components, root's component must have base
    if k+1 < len(dp_root):
        ans = dp_root[k+1][1]
    print(ans)

if __name__ == "__main__":
    solve()
